package com.burhan.site;

import android.app.Activity;
import android.content.*;
import android.content.res.ColorStateList;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import androidx.core.content.FileProvider;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import com.google.android.material.button.MaterialButton;
import org.json.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.ExecutorService;

/** Current camera-session journal only. Existing reports and prior derivative files are immutable. */
final class CaptureReview {
    interface Listener {void closed();void allFindings();void retake(String id);void updated(BurhanDatabase.CaptureRow row);}
    private final Activity activity;private final boolean ar;private final List<BurhanDatabase.CaptureRow> rows;private final ExecutorService worker;private final Listener listener;private final String retakeTarget;
    private final BottomSheetDialog dialog;private final LinearLayout content;private final TextView heading;private final ImageView image;private final FrameLayout imageBox;private final Button toggle,retake;private int index;private boolean original,handled,editing,busy;
    private MarkupView editor;
    CaptureReview(Activity activity,boolean ar,List<BurhanDatabase.CaptureRow> rows,ExecutorService worker,String activeTask,Listener listener){
        this.activity=activity;this.ar=ar;this.rows=rows;this.worker=worker;this.listener=listener;String target="";for(BurhanDatabase.CaptureRow row:rows)try{if(new JSONObject(row.json).optString("checkTaskId").equals(activeTask))target=row.id;}catch(Exception ignored){}retakeTarget=target;
        index=Math.max(0,rows.size()-1);dialog=new BottomSheetDialog(activity);content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(16,12,16,24);content.setBackgroundColor(0xff1d2024);content.setLayoutDirection(ar?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);ScrollView scroll=new ScrollView(activity);scroll.addView(content);dialog.setContentView(scroll);dialog.setOnDismissListener(d->{if(editor!=null)editor.release();if(!handled)listener.closed();});
        heading=new TextView(activity);heading.setTextColor(Color.WHITE);heading.setTextSize(20);content.addView(heading);
        imageBox=new FrameLayout(activity);image=new ImageView(activity);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription(t("Saved inspection evidence","دليل فحص محفوظ"));imageBox.addView(image,new FrameLayout.LayoutParams(-1,-1));content.addView(imageBox,new LinearLayout.LayoutParams(-1,(int)(activity.getResources().getDisplayMetrics().heightPixels*.42)));
        LinearLayout navigation=row();add(navigation,t("Previous","السابق"),()->{if(!editing&&index>0){index--;render();}});add(navigation,t("Next","التالي"),()->{if(!editing&&index+1<rows.size()){index++;render();}});content.addView(navigation);
        toggle=add(content,t("Show original","عرض الأصل"),()->{if(!editing){original=!original;render();}});
        retake=add(content,t("Retake latest for this check","إعادة التقاط أحدث دليل لهذا الفحص"),()->{if(!busy&&!editing&&!rows.isEmpty()){handled=true;String id=rows.get(index).id;dialog.dismiss();listener.retake(id);}});
        if(CameraPreferences.enabled(activity,"photoMarkup"))add(content,t("Markup · arrows and circles","تعليقات · أسهم ودوائر"),this::beginMarkup);
        if(CameraPreferences.enabled(activity,"individualPhotoSharing"))add(content,t("Share displayed image","مشاركة الصورة المعروضة"),this::share);
        add(content,t("Continue camera","متابعة الكاميرا"),dialog::dismiss);add(content,t("All findings","كل النتائج"),()->{handled=true;dialog.dismiss();listener.allFindings();});render();
    }
    void show(){dialog.show();dialog.getBehavior().setState(com.google.android.material.bottomsheet.BottomSheetBehavior.STATE_EXPANDED);}
    void dismiss(){handled=true;dialog.dismiss();}
    private void render(){if(editing)return;heading.setText(rows.isEmpty()?t("No session evidence yet","لا توجد أدلة لهذه الجلسة بعد"):t("Evidence ","دليل ")+(index+1)+" / "+rows.size());toggle.setEnabled(!rows.isEmpty());retake.setEnabled(!rows.isEmpty()&&rows.get(index).id.equals(retakeTarget));if(rows.isEmpty()){image.setImageDrawable(null);return;}try{JSONObject evidence=evidence();image.setImageURI(Uri.parse(evidence.getString(original?"original":"annotated")));toggle.setText(original?t("Show annotated","عرض التعليقات"):t("Show original","عرض الأصل"));String source=evidence.optString("captureSource","analysis");heading.append(" · "+evidence.optInt("width")+"×"+evidence.optInt("height")+" · "+source);}catch(Exception e){toast(t("Image unavailable","الصورة غير متاحة"));}}
    private JSONObject evidence() throws Exception{return new JSONObject(rows.get(index).json).getJSONObject("evidence");}
    private void beginMarkup(){if(rows.isEmpty()||editing||busy)return;try{JSONObject evidence=evidence();Bitmap baseline=BitmapFactory.decodeFile(Uri.parse(evidence.optString("detectorBaseline",evidence.getString("annotated"))).getPath());if(baseline==null)throw new IOException("Baseline unavailable");editor=new MarkupView(activity,baseline,evidence.optJSONObject("annotations"));editing=true;imageBox.addView(editor,new FrameLayout.LayoutParams(-1,-1));LinearLayout tools=row();add(tools,t("Arrow","سهم"),()->{if(!busy)editor.kind="arrow";});add(tools,t("Circle","دائرة"),()->{if(!busy)editor.kind="ellipse";});add(tools,t("Undo mark","تراجع"),()->{if(busy)return;if(editor.shapes.length()>0)editor.shapes.remove(editor.shapes.length()-1);editor.invalidate();});content.addView(tools,content.indexOfChild(imageBox)+1);Button save=add(content,t("Save markup","حفظ التعليقات"),()->saveMarkup(tools));Button cancel=add(content,t("Cancel markup","إلغاء التعليقات"),()->{imageBox.removeView(editor);editor.release();editing=false;content.removeView(tools);content.removeView(saveMarkupButton);content.removeView(cancelMarkupButton);render();});saveMarkupButton=save;cancelMarkupButton=cancel;}catch(Exception e){toast(t("Cannot open markup","تعذر فتح التعليقات"));}}
    private Button saveMarkupButton,cancelMarkupButton;
    private void saveMarkup(LinearLayout tools){if(busy)return;busy=true;saveMarkupButton.setEnabled(false);cancelMarkupButton.setEnabled(false);editor.setEnabled(false);final BurhanDatabase.CaptureRow row=rows.get(index);final Bitmap bitmap=editor.renderImage();final JSONArray shapes;try{shapes=new JSONArray(editor.shapes.toString());}catch(Exception invalid){busy=false;return;}worker.execute(()->{File derivative=null;try{JSONObject capture=new JSONObject(row.json),evidence=capture.getJSONObject("evidence");String baseline=evidence.optString("detectorBaseline",evidence.getString("annotated"));derivative=new File(activity.getFilesDir(),"evidence/"+row.id+"-markup-"+UUID.randomUUID()+".jpg");try(FileOutputStream out=new FileOutputStream(derivative)){if(!bitmap.compress(Bitmap.CompressFormat.JPEG,92,out))throw new IOException("Encoding failed");out.getFD().sync();}evidence.put("detectorBaseline",baseline).put("annotated",Uri.fromFile(derivative).toString()).put("annotations",new JSONObject().put("version",1).put("shapes",shapes));BurhanDatabase.CaptureRow updated=new BurhanDatabase.CaptureRow();updated.id=row.id;updated.inspectionId=row.inspectionId;updated.createdAt=row.createdAt;updated.json=capture.toString();BurhanDatabase.get(activity).store().updateCapture(updated);activity.runOnUiThread(()->{rows.set(index,updated);listener.updated(updated);imageBox.removeView(editor);editor.release();editing=false;busy=false;content.removeView(tools);content.removeView(saveMarkupButton);content.removeView(cancelMarkupButton);original=false;render();});}catch(Exception e){if(derivative!=null)derivative.delete();activity.runOnUiThread(()->{busy=false;saveMarkupButton.setEnabled(true);cancelMarkupButton.setEnabled(true);editor.setEnabled(true);toast(t("Markup not saved. Original preserved.","لم تُحفظ التعليقات. الأصل محفوظ."));});}finally{bitmap.recycle();}});}
    private void share(){if(rows.isEmpty()||busy||editing)return;try{File source=new File(Uri.parse(evidence().getString(original?"original":"annotated")).getPath());File folder=new File(activity.getCacheDir(),"shared-backups");if(!folder.exists()&&!folder.mkdirs())throw new IOException("Share unavailable");File copy=new File(folder,"Burhan-photo-"+UUID.randomUUID()+".jpg");Files.copy(source.toPath(),copy.toPath());Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".fileprovider",copy);Intent share=new Intent(Intent.ACTION_SEND).setType("image/jpeg").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri("Burhan evidence",uri));activity.startActivity(Intent.createChooser(share,t("Share evidence","مشاركة الدليل")));}catch(Exception e){toast(t("Could not share this image","تعذرت مشاركة الصورة"));}}
    private LinearLayout row(){LinearLayout result=new LinearLayout(activity);result.setOrientation(LinearLayout.HORIZONTAL);return result;}
    private Button add(LinearLayout parent,String title,Runnable action){MaterialButton button=new MaterialButton(activity);button.setText(title);button.setAllCaps(false);button.setMinHeight((int)(48*activity.getResources().getDisplayMetrics().density));button.setBackgroundTintList(ColorStateList.valueOf(0xff30353c));button.setTextColor(0xffffd43b);button.setOnClickListener(v->action.run());parent.addView(button,parent.getOrientation()==LinearLayout.HORIZONTAL?new LinearLayout.LayoutParams(0,-2,1):new LinearLayout.LayoutParams(-1,-2));return button;}
    private void toast(String text){Toast.makeText(activity,text,Toast.LENGTH_SHORT).show();}private String t(String en,String ar){return this.ar?ar:en;}
    static final class MarkupView extends View {
        private final Bitmap baseline;JSONArray shapes;String kind="arrow";private float startX,startY,endX,endY;private boolean drawing;
        MarkupView(Context context,Bitmap baseline,JSONObject annotation){super(context);this.baseline=baseline;shapes=annotation==null?new JSONArray():annotation.optJSONArray("shapes");if(shapes==null)shapes=new JSONArray();setContentDescription("Draw an arrow or circle on the evidence. Original preserved.");}
        void release(){if(!baseline.isRecycled())baseline.recycle();}
        private RectF bounds(){float scale=Math.min(getWidth()/(float)baseline.getWidth(),getHeight()/(float)baseline.getHeight());float w=baseline.getWidth()*scale,h=baseline.getHeight()*scale;return new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);}
        private float normal(float value,float start,float length){return Math.max(0,Math.min(1,(value-start)/length));}
        @Override public boolean onTouchEvent(MotionEvent event){RectF bounds=bounds();float x=normal(event.getX(),bounds.left,bounds.width()),y=normal(event.getY(),bounds.top,bounds.height());if(!isEnabled())return true;if(event.getAction()==MotionEvent.ACTION_DOWN){startX=endX=x;startY=endY=y;drawing=true;if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(true);return true;}if(event.getAction()==MotionEvent.ACTION_MOVE){endX=x;endY=y;invalidate();return true;}if(event.getAction()==MotionEvent.ACTION_UP){endX=x;endY=y;drawing=false;if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);try{if(shapes.length()<200&&Math.abs(endX-startX)+Math.abs(endY-startY)>.015f&&(!kind.equals("ellipse")||(Math.abs(endX-startX)>.003f&&Math.abs(endY-startY)>.003f)))shapes.put(new JSONObject().put("kind",kind).put("points",new JSONArray(new double[]{startX,startY,endX,endY})));}catch(Exception ignored){}invalidate();performClick();return true;}if(event.getAction()==MotionEvent.ACTION_CANCEL){drawing=false;if(getParent()!=null)if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);invalidate();}return true;}
        @Override public boolean performClick(){super.performClick();return true;}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(baseline.isRecycled())return;RectF bounds=bounds();canvas.save();canvas.translate(bounds.left,bounds.top);canvas.scale(bounds.width()/baseline.getWidth(),bounds.height()/baseline.getHeight());drawContent(canvas);if(drawing)shape(canvas,kind,new float[]{startX,startY,endX,endY});canvas.restore();}
        Bitmap renderImage(){Bitmap bitmap=baseline.copy(Bitmap.Config.ARGB_8888,true);Canvas canvas=new Canvas(bitmap);for(int i=0;i<shapes.length();i++){JSONObject shape=shapes.optJSONObject(i);if(shape==null)continue;JSONArray p=shape.optJSONArray("points");if(p!=null&&p.length()==4)shape(canvas,shape.optString("kind"),new float[]{(float)p.optDouble(0),(float)p.optDouble(1),(float)p.optDouble(2),(float)p.optDouble(3)});}return bitmap;}
        private void drawContent(Canvas canvas){canvas.drawBitmap(baseline,0,0,null);for(int i=0;i<shapes.length();i++){JSONObject shape=shapes.optJSONObject(i);if(shape==null)continue;JSONArray p=shape.optJSONArray("points");if(p!=null&&p.length()==4)shape(canvas,shape.optString("kind"),new float[]{(float)p.optDouble(0),(float)p.optDouble(1),(float)p.optDouble(2),(float)p.optDouble(3)});}}
        private void shape(Canvas canvas,String kind,float[] p){Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(0xffff653b);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Math.max(3,baseline.getWidth()/180f));float x=p[0]*baseline.getWidth(),y=p[1]*baseline.getHeight(),ex=p[2]*baseline.getWidth(),ey=p[3]*baseline.getHeight();if(kind.equals("ellipse"))canvas.drawOval(Math.min(x,ex),Math.min(y,ey),Math.max(x,ex),Math.max(y,ey),paint);else{canvas.drawLine(x,y,ex,ey,paint);double angle=Math.atan2(ey-y,ex-x);float size=baseline.getWidth()/30f;canvas.drawLine(ex,ey,ex-size*(float)Math.cos(angle-.6),ey-size*(float)Math.sin(angle-.6),paint);canvas.drawLine(ex,ey,ex-size*(float)Math.cos(angle+.6),ey-size*(float)Math.sin(angle+.6),paint);}}
    }
}
